  "loc.gpsTracker": "🛰️ GPS 트래커",
  "loc.guide1": "<b>‘Traccar Client’</b> 앱 설치(App Store 또는 Google Play, 무료).",
  "loc.guide2": "앱의 <b>기기 ID</b>(Device identifier)에 입력:",
  "loc.guide3": "<b>서버 URL</b>에 입력:",
  "loc.guide4": "정확도 <b>중간</b>, 거리 <b>50 m</b>. 이제 앱은 이동할 때만 보냅니다 – 정지 중에는 보내지 않습니다. 다른 항목(간격, 하트비트)이 있으면 하트비트를 끄거나 0으로.",
  "loc.guide5": "위치 접근 허용: <b>항상</b>, <b>정확한 위치</b> 켜기.",
  "loc.guide6": "<b>서비스 / 추적</b> 스위치를 켜고 <b>항상 켜 두세요</b> – 끝. 이제 모든 것을 pinn.에서 조작합니다: ‘계속 전송’ 켜기/끄기, ‘1회 전송’, SOS. ‘계속 전송’이 꺼져 있는 동안은 아무도 위치를 볼 수 없고 pinn.은 경로를 기록하지 않습니다.",
  "loc.guideIntro": "다른 앱 없이도 ‘📍 위치 공유’는 pinn.에서 바로 됩니다 – 단, pinn.이 열려 있는 동안만입니다. pinn.이 닫히고 화면이 잠겨 있어도 위치가 오도록 무료 앱 ‘Traccar Client’가 pinn.으로 바로 보냅니다(Traccar 서버 불필요). iPhone과 Android 모두 같습니다.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. 트래커가 모바일 네트워크로 연결하므로 이 포트는 FRITZ!Box에서 NAS로 포워딩해야 해요.",
  "loc.haveGoodTripFamily": "잘 다녀오세요! 가족에게 알렸어요.",
