  "loc.setup": "설정 · {famDeviceName}",
  "loc.setupIntro": "휴대폰은 다른 것이 필요 없습니다: 누구나 ‘내 위치’에서 pinn.으로 바로 공유할 수 있습니다. 백그라운드(pinn. 닫힘)에서는 무료 앱 ‘Traccar Client’(iPhone 및 Android)가 pinn.으로 바로 보냅니다 – Traccar 서버는 필요 없습니다. SIM 카드가 있는 GPS 추적기(예: 목걸이)만 ‘traccar’ 컨테이너가 필요합니다. 위치는 여러분의 NAS에 남습니다.",
