  "loc.shareIntro#wg": "셰어하우스가 지도에서 실시간으로 당신을 봅니다. 이동할 때만 전송하고 정지 중에는 보내지 않습니다. pinn.이 닫혀 있으면 한 번 설정한 ‘Traccar Client’ 앱이 보냅니다.",
