  "loc.testSameProcessReal#wg": "테스트: 실제 도움 요청과 같은 과정(푸시, 팝업, 지도, 주소)이지만 나에게만 가고 셰어하우스는 알아채지 못해요.",
  "loc.tipSetAddressUnder": "팁: 설정 → 집에서 주소를 설정하면 ‘집’ 장소가 자동으로 만들어지고 도착·출발 푸시를 쓸 수 있어요.",
  "loc.traccarClientChooseSend": "‘Traccar Client’에서 ‘SOS 보내기’를 선택하세요(버전에 따라 앱 안에서 또는 앱 아이콘을 길게 눌러서). pinn.이 위치, 주소, 시간, 전화와 긴급 신고 {regionNotrufText} 버튼과 함께 즉시 모든 가족에게 푸시로 알려요. 팁: 응급 카드에 내 휴대폰 번호를 입력해 두세요.",
  "loc.traccarClientChooseSend#wg": "‘Traccar Client’에서 ‘SOS 보내기’를 선택하세요(버전에 따라 앱 안에서 또는 앱 아이콘을 길게 눌러서). pinn.이 위치, 주소, 시간, 전화와 긴급 신고 {regionNotrufText} 버튼과 함께 즉시 모든 셰어하우스에게 푸시로 알려요. 팁: 응급 카드에 내 휴대폰 번호를 입력해 두세요.",
