  "maint.dev.report": "뭔가 발견하면 버전, 기기, 하고 있던 일과 함께 GitHub에 신고해 주세요. 오류 로그의 내용이 도움이 돼요.",
  "maint.dev.safe": "데이터는 사라지지 않아요. 설치 전에 pinn.이 자동으로 백업을 만들어요(‘업데이트 전’). ‘복원’ → ‘전부’로 언제든 이전 상태로 돌아갈 수 있어요. 완성된 버전이 나오면 일반 업데이트로 안내돼요.",
  "maint.dev.title": "🧪 개발자: 테스트 사전 릴리스",
  "maint.dev.warnBugs": "사전 릴리스에는 버그가 있을 수 있어요. 기능이 바뀌거나, 미완성이거나, 다시 제거될 수 있어요.",
  "maint.dev.warnDaily": "일상에서 pinn.에 의존한다면 권장하지 않아요. 예를 들어 일정, 알림, 응급 카드 등이에요.",
