  "settings.calendar.info": "각 프로필은 자신의 iCloud 또는 Google 계정으로 로그인하고 거기서 캘린더를 선택해요. ‘나를 위해’는 내 프로필에만 보이고, ‘가족’은 가족 모두에게 보이고 사용돼요. 다른 사람에게는 가족 캘린더가 어느 계정의 것인지만 가려진 형태(예: m**l@g***l.com)로 보여요. 일정은 평소처럼 만들고, 수정하고, 옮길 수 있으며 오프라인에서도 대기열에 쌓였다가 iCloud나 Google(그리고 휴대폰)에 바로 반영돼요. 동기화는 15분마다 또는 ‘지금 업데이트’로 해요. 계정이 없어도 pinn. 서버에만 있는 캘린더는 쓸 수 있어요. 알림과 일일 요약은 푸시로 와요. 비공개 일정은 본인에게만 가요.",
