  "smart.guide1": "1. 새 단축어 ‘pinn Automatik’:",
  "smart.guide10": "이를 위해 기기가 pinn.에 연결될 수 있어야 해요(집 Wi-Fi 또는 VPN). 각 동작은 할 일당 한 번만 실행돼요. 이미 버튼으로 시작한 동작은 자동화로 다시 시작되지 않아요.",
  "smart.guide2": "• ‘URL의 내용 가져오기’ – 위의 링크를 붙여넣으세요",
  "smart.guide3": "• ‘사전 값 가져오기’ – 키 ‘aktionen’",
  "smart.guide4": "• ‘각 항목 반복’, 그 안에서:",
  "smart.guide5": "– ‘사전 값 가져오기’ – 키 ‘eingabe’를 ‘반복 항목’에서",
  "smart.guide6": "– ‘사전 값 가져오기’ – 키 ‘kurzbefehl’을 ‘반복 항목’에서",
  "smart.guide7": "– ‘단축어 실행’ – 단축어에는 값 ‘kurzbefehl’, 입력에는 값 ‘eingabe’를 선택하세요",
  "smart.guide8": "2. ‘자동화’ 탭 → ‘하루 중 시간’ – 시간마다 자동화를 하나씩 위에 만들고, ‘즉시 실행’ → ‘pinn Automatik’.",
  "smart.guide9": "3. 팁: ‘도착’(집) → ‘pinn Automatik’도 추가하면 놓친 것을 따라잡을 수 있어요.",
  "smart.haAddress": "주소",
  "smart.haAddressHint": "브라우저에 입력하는 것과 같은 IP 주소만 입력하세요. pinn.이 http://, https://, 포트(8123)를 알아서 시도해요. ‘homeassistant.local’은 여기서 작동하지 않으니 IP를 사용하세요(Home Assistant → 설정 → 시스템 → 네트워크 또는 라우터).",
  "smart.haAddressPh": "예: 192.168.178.10",
