  "smart.haConnectFirst": "Home Assistant가 아직 연결되지 않았어요. ‘Home Assistant’ 탭에서 연결하세요.",
  "smart.haConnected": "✓ 연결됨",
  "smart.haConnectedTo": "✓ {place}에 연결됨",
  "smart.haDevices": "Home Assistant를 통한 기기: {list}",
  "smart.haIntro": "pinn. 서버가 Home Assistant를 직접 제어해요. 버튼은 Android를 포함한 모든 기기에서 작동하고, 자동화와 ‘체크 시’는 단축어 없이 실행돼요. 상태 엔티티가 있으면 pinn.이 로봇청소기 등이 정말 끝날 때까지 기다려요.",
  "smart.haNeedAddress": "주소를 입력해 주세요.",
  "smart.haNoDevices": "Home Assistant를 통한 기기가 아직 없어요. ‘기기’ 탭에서 기기를 만들고 ‘Home Assistant’를 선택하세요.",
  "smart.haNotConnected": "Home Assistant가 아직 연결되지 않았어요.",
  "smart.haOff": "Home Assistant 연결 안 됨",
  "smart.haOn": "Home Assistant 연결됨",
  "smart.haSearching": "Home Assistant 검색 중…",
  "smart.haTip1": "Roborock: ‘로봇청소기’ 기기를 만들고 위에서 로봇(vacuum.…)을 선택하면 pinn.이 지도에서 방을 불러와요. 동작마다 ‘방 청소’에서 방과 모드(청소기, 청소기+물걸레, 물걸레)를 선택해요. ‘할 일의 방’은 집안일 청소 할 일의 방을 사용하므로 이름은 Roborock 앱과 같아야 해요.",
  "smart.haTip2": "로봇 자체도 상태로 쓰여서, 독에 돌아온 뒤에야 다음 동작이 시작돼요.",
  "smart.haTip3": "스크립트는 방 이름을 변수 <span class=\"font-mono\">raum</span>으로 받아요. 그래서 스크립트 하나로 모든 방을 처리할 수 있어요.",
  "smart.haTip4": "조명/LED: 동작에서 색상과 밝기를 바로 설정해요.",
  "smart.haTip5": "자동화는 서버에서 매분 실행돼요. 휴대폰에서 자동화를 설정할 필요가 없어요.",
  "smart.haToken": "장기 액세스 토큰",
  "smart.haTokenHint": "Home Assistant에서: 왼쪽 아래 프로필 → ‘보안’ 탭 → ‘장기 액세스 토큰’ → ‘토큰 만들기’를 누르고 긴 문자열을 그대로 붙여넣으세요. 앞에 ‘Bearer’를 쓸 필요는 없어요. pinn.이 알아서 붙여요(써도 괜찮아요). 토큰은 서버에 보관되고 기기로는 전송되지 않아요.",
  "smart.haTokenKeep": "비워 두면 이전 토큰 유지",
