  "smart.howTo": "설정 방법",
  "smart.howTo1": "1. 기기를 만들고 Apple 단축어로 실행할지 Home Assistant로 실행할지 선택하세요.",
  "smart.howTo2": "2. 동작을 설정하세요(단축어 이름 또는 Home Assistant의 엔티티). ‘▶ 테스트’로 바로 시험해 볼 수 있어요. 소요 시간이나 상태 엔티티가 있으면 같은 기기의 동작은 차례대로 실행돼요.",
